{'role': 'user', 'content': [{'tool_use_id': 'toolu_0182YYxH4h71gg3HvrSKYnCu', 'type': 'tool_result', 'content': '     1→/**
     2→ * Compatibility checker.
     3→ *
     4→ * Determines whether a folder contains a compatible THE_FACTORY protocol
     5→ * project by verifying the presence of required files and directories.
     6→ *
     7→ * Required:
     8→ *   - AGENT_BOOTSTRAP.md
     9→ *   - preambles/COMMON_RULES.md
    10→ *   - At least one role preamble in preambles/ (any .md other than COMMON_RULES.md)
    11→ *   - templates/  (directory)
    12→ *   - docs/agents/orchestrator-state.md
    13→ *
    14→ * Returns a ProjectConfig — never throws.
    15→ */
    16→
    17→import fs from "fs";
    18→import path from "path";
    19→import type { ProjectConfig } from "@/types/index";
    20→
    21→const REQUIRED_FILES = [
    22→  "AGENT_BOOTSTRAP.md",
    23→  "preambles/COMMON_RULES.md",
    24→  "templates",                         // directory
    25→  "docs/agents/orchestrator-state.md",
    26→] as const;
    27→
    28→/**
    29→ * Attempt to derive a human-readable project name from the folder or from
    30→ * the first heading in AGENT_BOOTSTRAP.md.
    31→ */
    32→function deriveProjectName(projectPath: string): string {
    33→  // Try to read the first H1 from AGENT_BOOTSTRAP.md
    34→  const bootstrapPath = path.join(projectPath, "AGENT_BOOTSTRAP.md");
    35→  try {
    36→    const content = fs.readFileSync(bootstrapPath, "utf-8");
    37→    const match = content.match(/^#\s+(.+)$/m);
    38→    if (match && match[1]) {
    39→      return match[1].trim();
    40→    }
    41→  } catch {
    42→    // Fall through to folder name
    43→  }
    44→
    45→  return path.basename(projectPath);
    46→}
    47→
    48→/**
    49→ * Check whether the directory at `projectPath` contains a compatible
    50→ * protocol project structure.
    51→ *
    52→ * @param projectPath  Absolute path to the directory to check
    53→ */
    54→export function checkCompatibility(projectPath: string): ProjectConfig {
    55→  const missing: string[] = [];
    56→
    57→  // Check each required file/directory
    58→  for (const required of REQUIRED_FILES) {
    59→    const fullPath = path.join(projectPath, required);
    60→    try {
    61→      const stat = fs.statSync(fullPath);
    62→      // "templates" must be a directory
    63→      if (required === "templates" && !stat.isDirectory()) {
    64→        missing.push(required);
    65→      }
    66→    } catch {
    67→      missing.push(required);
    68→    }
    69→  }
    70→
    71→  // Check for at least one role preamble
    72→  const preambleDir = path.join(projectPath, "preambles");
    73→  let hasRolePreamble = false;
    74→  try {
    75→    const entries = fs.readdirSync(preambleDir);
    76→    hasRolePreamble = entries.some(
    77→      (e) => e.endsWith(".md") && e !== "COMMON_RULES.md"
    78→    );
    79→  } catch {
    80→    // preambles dir missing — already flagged above via COMMON_RULES.md check
    81→  }
    82→
    83→  if (!hasRolePreamble) {
    84→    missing.push("preambles/<role>.md (at least one role preamble required)");
    85→  }
    86→
    87→  const projectName = deriveProjectName(projectPath);
    88→
    89→  return {
    90→    projectPath,
    91→    projectName,
    92→    compatible: missing.length === 0,
    93→    missing,
    94→  };
    95→}
    96→'}]}

