    63→  for (const line of lines) {
    64→    // Match: - `path` — purpose  OR  - `path` (purpose)  OR  - `path`
    65→    const match = line.match(
    66→      /^\s*[-*]\s*`([^`]+)`(?:\s*[—–-]+\s*(.+)|\s*\(([^)]+)\))?/
    67→    );
    68→    if (match) {
    69→      const filePath = match[1].trim();
    70→      const purpose = (match[2] ?? match[3] ?? "Context file").trim();
