    11→
    12→import fs from "fs";
    13→import path from "path";
    14→import type { NextAction } from "@/types/index";
    15→
    16→const FALLBACK: NextAction = {
    17→  role: "unknown",
    18→  reason: "Unable to determine — orchestrator state not found",
    19→  launchPackageUrl: "",
    20→};
    21→
    22→/**
    23→ * Extract the first "Next Session Priorities" entry from orchestrator state
    24→ * content.
    25→ *
    26→ * Looks for a section like:
    27→ *   ## Next Session Priorities
    28→ *   1. Developer — implement X
    29→ *   2. Validator — verify Y
    30→ *
    31→ * Returns { role, reason } or null if the section cannot be found.
    32→ */
    33→function parseNextPriority(content: string): { role: string; reason: string } | null {
    34→  // Find the "Next Session Priorities" section
    35→  const sectionMatch = content.match(
    36→    /##\s*Next Session Priorities\b([\s\S]*?)(?=\n##\s|\s*$)/i
    37→  );
    38→  if (!sectionMatch) return null;
    39→
    40→  const section = sectionMatch[1];
    41→
    42→  // Match ordered or unordered list item: "1. Role — reason" or "- Role — reason"
    43→  const itemMatch = section.match(
    44→    /^\s*(?:\d+\.|[-*])\s+([A-Za-z][A-Za-z0-9 _-]*)(?:\s*[—–-]+\s*(.+))?/m
    45→  );
    46→  if (!itemMatch) return null;
    47→
    48→  const role = itemMatch[1].trim().toLowerCase().replace(/\s+/g, "-");
    49→  const reason = itemMatch[2]
    50→    ? itemMatch[2].trim()
    51→    : `${itemMatch[1].trim()} is next in the pipeline`;
    52→
    53→  return { role, reason };
    54→}
    55→
    56→/**
    57→ * Derive the next recommended action from the orchestrator state file.
    58→ *
    59→ * @param projectPath  Absolute path to the attached project
    60→ */
    61→export function deriveNextAction(projectPath: string): NextAction {
    62→  const stateFilePath = path.join(projectPath, "docs/agents/orchestrator-state.md");
    63→
    64→  let content: string;
    65→  try {
    66→    content = fs.readFileSync(stateFilePath, "utf-8");
    67→  } catch {
    68→    return FALLBACK;
    69→  }
    70→
    71→  const priority = parseNextPriority(content);
    72→  if (!priority) {
    73→    return {
    74→      role: "unknown",
    75→      reason: "Unable to determine — Next Session Priorities section not found",
    76→      launchPackageUrl: "",
    77→    };
    78→  }
    79→
    80→  return {
    81→    role: priority.role,
    82→    reason: priority.reason,
    83→    launchPackageUrl: `/api/launch-package?role=${encodeURIComponent(priority.role)}`,
    84→  };
    85→}
    86→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01MRW99nZQw6tBakyJETQFXj', 'type': 'tool_result', 'content': '     1→/**
     2→ * Decision scanner.
     3→ *
     4→ * Scans indexed artifact files for [DECISION NEEDED] and [ASK OPERATOR]
     5→ * markers, extracts the question text and surrounding context, and returns
     6→ * a deterministic list of DecisionItem objects.
     7→ *
     8→ * ID generation: sha256-like deterministic hash of (sourceFile + lineNumber).
     9→ * We use a simple djb2 hash to avoid a crypto dependency.
    10→ */
    11→
    12→import fs from "fs";
    13→import path from "path";
    14→import type { DecisionItem } from "@/types/index";
    15→import type { ArtifactIndex } from "@/lib/artifact-engine/index";
    16→
    17→type Marker = "[DECISION NEEDED]" | "[ASK OPERATOR]";
    18→
    19→const MARKERS: Marker[] = ["[DECISION NEEDED]", "[ASK OPERATOR]"];
    20→
    21→/** Simple djb2 hash → hex string for deterministic IDs. */
    22→function djb2(str: string): string {
    23→  let hash = 5381;
    24→  for (let i = 0; i < str.length; i++) {
    25→    hash = (hash * 33) ^ str.charCodeAt(i);
    26→    hash = hash >>> 0; // keep 32-bit unsigned
    27→  }
    28→  return hash.toString(16).padStart(8, "0");
    29→}
    30→
    31→function makeId(sourceFile: string, lineNumber: number): string {
    32→  return djb2(`${sourceFile}:${lineNumber}`);
    33→}
    34→
    35→/**
    36→ * Scan a single file for decision markers.
    37→ *
    38→ * @param absolutePath  Absolute path to the file
    39→ * @param relativePath  Relative path (used for sourceFile field)
    40→ * @returns             Array of DecisionItem found in the file
    41→ */
    42→function scanFile(absolutePath: string, relativePath: string): DecisionItem[] {
    43→  let content: string;
    44→  try {
    45→    content = fs.readFileSync(absolutePath, "utf-8");
    46→  } catch {
    47→    return [];
    48→  }
    49→
    50→  const lines = content.split("\n");
    51→  const items: DecisionItem[] = [];
    52→
    53→  for (let i = 0; i < lines.length; i++) {
    54→    const line = lines[i];
    55→    const lineNumber = i + 1; // 1-based
    56→
    57→    for (const marker of MARKERS) {
    58→      const markerIndex = line.indexOf(marker);
    59→      if (markerIndex === -1) continue;
    60→
    61→      // Extract question text: everything after the marker on the same line
    62→      const afterMarker = line.slice(markerIndex + marker.length).trim();
    63→      // Strip leading punctuation like ": " or "— "
    64→      const question = afterMarker.replace(/^[:\s—–-]+/, "").trim() || line.trim();
    65→
    66→      // Surrounding context: 1 line before and after (clamped to array bounds)
    67→      const contextLines: string[] = [];
    68→      if (i > 0) contextLines.push(lines[i - 1]);
    69→      contextLines.push(line);
    70→      if (i < lines.length - 1) contextLines.push(lines[i + 1]);
    71→      const context = contextLines.join("\n");
    72→
    73→      items.push({
    74→        id: makeId(relativePath, lineNumber),
    75→        marker,
    76→        question,
    77→        sourceFile: relativePath,
    78→        lineNumber,
    79→        context,
    80→      });
    81→    }
    82→  }
    83→
    84→  return items;
    85→}
    86→
    87→/**
    88→ * Scan all indexed artifacts for decision markers.
    89→ *
    90→ * @param index        The ArtifactIndex to enumerate file paths from
    91→ * @param projectPath  Absolute path to the project root
    92→ */
    93→export function scanDecisions(
    94→  index: ArtifactIndex,
    95→  projectPath: string
    96→): DecisionItem[] {
    97→  const artifacts = index.getAll();
    98→  const items: DecisionItem[] = [];
    99→
   100→  for (const artifact of artifacts) {
   101→    const absolutePath = path.join(projectPath, artifact.path);
   102→    const found = scanFile(absolutePath, artifact.path);
   103→    items.push(...found);
   104→  }
   105→
   106→  return items;
   107→}
   108→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01SveKqtUBRYcQSxbEeBMWcP', 'type': 'tool_result', 'content': '     1→/**
     2→ * Frontmatter parser for protocol artifacts.
     3→ * Uses gray-matter to extract YAML frontmatter and derives ArtifactType
     4→ * from file path conventions. Never throws — returns a parse-error record
     5→ * on malformed input.
     6→ */
     7→
     8→import matter from "gray-matter";
     9→import path from "path";
    10→import fs from "fs";
    11→import type { ArtifactRecord, ArtifactType } from "@/types/index";
    12→
    13→/**
    14→ * Derive an ArtifactType from the file path and optional frontmatter data.
    15→ * Path conventions take precedence; frontmatter can refine the result.
    16→ */
    17→export function deriveArtifactType(
    18→  filePath: string,
    19→  frontmatter: Record<string, unknown>
    20→): ArtifactType {
    21→  const normalized = filePath.replace(/\\/g, "/").toLowerCase();
    22→  const basename = path.basename(normalized);
    23→
    24→  // Explicit frontmatter override
    25→  const fmType = frontmatter["artifact_type"] as string | undefined;
    26→  if (fmType) {
    27→    const valid: ArtifactType[] = [
    28→      "spec",
    29→      "plan",
    30→      "tasks",
    31→      "session-summary",
    32→      "handoff-packet",
    33→      "validator-verdict",
    34→      "qa-verdict",
    35→      "research-request",
    36→      "research-findings",
    37→      "orchestrator-state",
    38→    ];
    39→    if (valid.includes(fmType as ArtifactType)) {
    40→      return fmType as ArtifactType;
    41→    }
    42→  }
    43→
    44→  // Path-based derivation — more specific patterns checked first to avoid
    45→  // a broad match (e.g. /specs/) swallowing a session-summary inside specs/.
    46→
    47→  if (basename === "orchestrator-state.md" || normalized.includes("orchestrator-state")) {
    48→    return "orchestrator-state";
    49→  }
    50→  if (normalized.includes("session-summary") || normalized.includes("session_summary")) {
    51→    return "session-summary";
    52→  }
    53→  if (normalized.includes("handoff")) {
    54→    return "handoff-packet";
    55→  }
    56→  if (normalized.includes("validator-verdict")) {
    57→    return "validator-verdict";
    58→  }
    59→  if (normalized.includes("qa-verdict")) {
    60→    return "qa-verdict";
    61→  }
    62→  if (normalized.includes("research-request")) {
    63→    return "research-request";
    64→  }
    65→  if (normalized.includes("research-findings")) {
    66→    return "research-findings";
    67→  }
    68→  if (normalized.includes("/specs/") || basename.startsWith("spec-") || basename === "spec.md") {
    69→    return "spec";
    70→  }
    71→  if (normalized.includes("/plans/") || basename.startsWith("plan-") || basename === "plan.md") {
    72→    return "plan";
    73→  }
    74→  if (basename === "tasks.md" || basename.startsWith("tasks-") || normalized.includes("/tasks/")) {
    75→    return "tasks";
    76→  }
    77→
    78→  return "unknown";
    79→}
    80→
    81→/**
    82→ * Parse a single markdown artifact file.
    83→ * Returns an ArtifactRecord with status "parse-error" if the file is
    84→ * unreadable or its frontmatter is malformed — never throws.
    85→ *
    86→ * @param filePath  Absolute path to the .md file
    87→ * @param projectRoot  Absolute path to the project root (for relative path calculation)
    88→ */
    89→export function parseArtifact(filePath: string, projectRoot: string): ArtifactRecord {
    90→  const name = path.basename(filePath, ".md");
    91→  const relativePath = path.relative(projectRoot, filePath);
    92→
    93→  let lastModified: string;
    94→  try {
    95→    const stat = fs.statSync(filePath);
    96→    lastModified = stat.mtime.toISOString();
    97→  } catch {
    98→    lastModified = new Date().toISOString();
    99→  }
   100→
   101→  let raw: string;
   102→  try {
   103→    raw = fs.readFileSync(filePath, "utf-8");
   104→  } catch {
   105→    return {
   106→      path: relativePath,
   107→      name,
   108→      type: "unknown",
   109→      status: "parse-error",
   110→      supersedes: null,
   111→      superseded_by: null,
   112→      lastModified,
   113→      frontmatter: {},
   114→    };
   115→  }
   116→
   117→  let parsed: matter.GrayMatterFile<string>;
   118→  try {
   119→    parsed = matter(raw);
   120→  } catch {
   121→    return {
   122→      path: relativePath,
   123→      name,
   124→      type: deriveArtifactType(filePath, {}),
   125→      status: "parse-error",
   126→      supersedes: null,
   127→      superseded_by: null,
   128→      lastModified,
   129→      frontmatter: {},
   130→    };
   131→  }
   132→
   133→  const fm = (parsed.data ?? {}) as Record<string, unknown>;
   134

