{'role': 'user', 'content': [{'tool_use_id': 'toolu_011zxCeygfK8XZXrURzT2mpR', 'type': 'tool_result', 'content': '     1→/**
     2→ * Singleton initializer for the Artifact Engine.
     3→ *
     4→ * Ensures the ArtifactIndex is created and started only once per server
     5→ * process. Wires index events to the EventBus so SSE clients receive
     6→ * real-time updates.
     7→ *
     8→ * All API routes that need artifact data should import `getArtifactIndex()`
     9→ * from this module rather than constructing their own ArtifactIndex.
    10→ */
    11→
    12→import { ArtifactIndex } from "./index";
    13→import { eventBus } from "./event-bus";
    14→import { getSettings } from "@/lib/settings";
    15→
    16→let instance: ArtifactIndex | null = null;
    17→let currentProjectPath: string | null = null;
    18→
    19→/**
    20→ * Returns the running ArtifactIndex singleton.
    21→ * Starts (or restarts) the engine if the project path has changed.
    22→ * Returns null if no project path is configured.
    23→ */
    24→export async function getArtifactIndex(): Promise<ArtifactIndex | null> {
    25→  const settings = getSettings();
    26→  const projectPath = settings.projectPath;
    27→
    28→  if (!projectPath) {
    29→    return null;
    30→  }
    31→
    32→  // Restart if project path changed
    33→  if (instance && currentProjectPath !== projectPath) {
    34→    await instance.stop();
    35→    instance = null;
    36→    currentProjectPath = null;
    37→  }
    38→
    39→  if (!instance) {
    40→    const idx = new ArtifactIndex(projectPath);
    41→
    42→    // Wire index events to the EventBus
    43→    idx.on("change", (record) => {
    44→      eventBus.emitArtifactChanged(record);
    45→    });
    46→    idx.on("remove", (relativePath) => {
    47→      eventBus.emitArtifactRemoved(relativePath);
    48→    });
    49→    idx.on("error", (...args: unknown[]) => {
    50→      // Surface watcher errors (e.g. project folder deleted while running)
    51→      const err = args[0];
    52→      const errMsg = err instanceof Error ? err.message : String(err);
    53→      const message =
    54→        errMsg.toLowerCase().includes("enoent") ||
    55→        errMsg.toLowerCase().includes("no such file")
    56→          ? "Project folder not found. Please re-attach your project."
    57→          : `Watcher error: ${errMsg}`;
    58→      eventBus.emitProjectError(message);
    59→    });
    60→
    61→    await idx.start();
    62→    instance = idx;
    63→    currentProjectPath = projectPath;
    64→  }
    65→
    66→  return instance;
    67→}
    68→
    69→/**
    70→ * Returns the ArtifactIndex synchronously without starting it.
    71→ * Used in contexts where async is not available. Returns null if not yet
    72→ * initialized.
    73→ */
    74→export function getArtifactIndexSync(): ArtifactIndex | null {
    75→  return instance;
