{'role': 'user', 'content': [{'tool_use_id': 'toolu_015kkqDyoWXi3FTixvKfuonb', 'type': 'tool_result', 'content': '     1→"use client";
     2→
     3→import { useRef, useEffect, useState } from "react";
     4→import { Mascot } from "@/components/ui/mascot";
     5→import type { MascotRole } from "@/components/ui/mascot";
     6→import type { RoleStatus } from "@/types";
     7→
     8→interface MascotCardProps {
     9→  role: MascotRole;
    10→  label: string;
    11→  description: string;
    12→  status: RoleStatus;
    13→  isRecommended: boolean;
    14→  isOpen: boolean;
    15→  onClick: () => void;
    16→}
    17→
    18→const STATUS_LABEL: Record<RoleStatus, string> = {
    19→  idle: "Ready",
    20→  launched: "Launched",
    21→  "awaiting-output": "Working\u2026",
    22→  complete: "Done",
    23→};
    24→
    25→export function MascotCard({
    26→  role,
    27→  label,
    28→  description,
    29→  status,
    30→  isRecommended,
    31→  isOpen,
    32→  onClick,
    33→}: MascotCardProps) {
    34→  const [pulse, setPulse] = useState(false);
    35→  const cardRef = useRef<HTMLButtonElement>(null);
    36→
    37→  // Expose scroll-and-pulse to parent via ref
    38→  useEffect(() => {
    39→    if ((cardRef.current as HTMLButtonElement & { triggerPulse?: () => void })) {
    40→      (cardRef.current as HTMLButtonElement & { triggerPulse?: () => void }).triggerPulse = () => {
    41→        cardRef.current?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    42→        setPulse(true);
    43→        setTimeout(() => setPulse(false), 600);
    44→      };
    45→    }
    46→  });
    47→
    48→  const borderColor = (() => {
    49→    if (pulse) return "border-ts-accent shadow-[0_0_0_3px_rgba(217,123,61,0.3)]";
    50→    if (isRecommended) return "border-ts-accent border-2";
    51→    if (status === "complete") return "border-ts-success";
    52→    if (status === "launched" || status === "awaiting-output") return "border-ts-launched";
    53→    return "border-ts-border";
    54→  })();
    55→
    56→  const bgColor = isRecommended ? "bg-[#FFF8F2]" : "bg-ts-surface";
    57→
    58→  const dotColor = (() => {
    59→    if (status === "complete") return "bg-ts-success";
    60→    if (status === "launched" || status === "awaiting-output") return "bg-ts-launched";
    61→    return "bg-ts-idle";
    62→  })();
    63→
    64→  const isPulsing = status === "awaiting-output";
    65→
    66→  return (
    67→    <button
    68→      ref={cardRef}
    69→      onClick={onClick}
    70→      className={[
    71→        "w-full text-left rounded-xl border p-5 shadow-sm cursor-pointer",
    72→        "transition-all duration-300 ease",
    73→        "focus:outline-none focus-visible:ring-2 focus-visible:ring-ts-accent focus-visible:ring-offset-2",
    74→        borderColor,
    75→        bgColor,
    76→        isOpen ? "ring-2 ring-ts-accent ring-offset-1" : "",
    77→      ].join(" ")}
    78→      aria-pressed={isOpen}
    79→      id={`mascot-card-${role}`}
    80→    >
    81→      <div className="flex items-start gap-3">
    82→        <Mascot role={role} size={48} />
    83→        <div className="flex-1 min-w-0">
    84→          <div className="flex items-center gap-2 mb-1">
    85→            <span className="text-sm font-semibold text-ts-text truncate">
    86→              {label}
    87→            </span>
    88→            {isRecommended && (
    89→              <span className="inline-flex items-center rounded-full bg-ts-accent/10 px-2 py-0.5 text-xs font-medium text-ts-accent whitespace-nowrap">
    90→                Up next
    91→              </span>
    92→            )}
    93→          </div>
    94→          <p className="text-xs text-ts-text-muted line-clamp-2 mb-3">
    95→            {description}
    96→          </p>
    97→          <div className="flex items-center gap-1.5">
    98→            <span
    99→              className={[
   100→                "inline-block w-2 h-2 rounded-full",
   101→                dotColor,
   102→                isPulsing ? "animate-pulse" : "",
   103→              ].join(" ")}
   104→              aria-hidden
   105→            />
   106→            <span className="text-xs text-ts-text-muted">
   107→              {STATUS_LABEL[status]}
   108→            </span>
   109→          </div>
   110→        </div>
   111→      </div>
   112→    </button>
   113→  );
   114→}
   115→
   116→export type { MascotCardProps };
   117→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01GbKbX3ykpzYGxhhG6hoKWR', 'type': 'tool_result', 'content': '     1→/**
     2→ * GET /api/launch-package?role={role}
     3→ *
     4→ * Returns a LaunchPackage for the specified role.
     5→ * 400 if role param is missing.
     6→ * 404 if the startup prompt for that role doesn't exist.
     7→ */
     8→
     9→import { NextRequest, NextResponse } from "next/server";
    10→import { assembleLaunchPackage } from "@/lib/launch-package";
    11→import { getSettings } from "@/lib/settings";
    12→
    13→export const dynamic = "force-dynamic";
    14→
    15→export async function GET(req: NextRequest): Promise<NextResponse> {
    16→  const { searchParams } = new URL(req.url);
    17→  const role = searchParams.get("role");
    18→
    19→  if (!role) {
    20→    return NextResponse.json(
    21→      { error: "Missing required query param: role" },
    22→      { status: 400 }
    23→    );
    24→  }
    25→
    26→  const settings = getSettings();
    27→  const projectPath = settings.projectPath;
    28→
    29→  if (!projectPath) {
    30→    return NextResponse.json({ error: "No project attached" }, { status: 404 });
    31→  }
    32→
    33→  const launchPackage = assembleLaunchPackage(role, projectPath);
    34→
    35→  if (!launchPackage) {
    36→    return NextResponse.json(
    37→      { error: `Startup prompt not found for role: ${role}` },
    38→      { status: 404 }
    39→    );
    40→  }
    41→
    42→  return NextResponse.json(launchPackage);
    43→}
    44→'}]}

