{'role': 'user', 'content': [{'tool_use_id': 'toolu_017tvgXrLb4b41u6jv8usuuX', 'type': 'tool_result', 'content': '     1→/**
     2→ * In-memory artifact index.
     3→ *
     4→ * Maintains a Map<relativePath, ArtifactRecord> that stays in sync with the
     5→ * filesystem via the file watcher. On startup it does a full directory scan
     6→ * to populate the index, then watches for incremental changes.
     7→ *
     8→ * Exposes change events for the SSE layer to subscribe to.
     9→ *
    10→ * Usage:
    11→ *   const index = new ArtifactIndex("/path/to/project");
    12→ *   await index.start();
    13→ *   index.on("change", (record) => { ... });
    14→ *   index.on("remove", (path) => { ... });
    15→ */
    16→
    17→import { EventEmitter } from "events";
    18→import fs from "fs";
    19→import path from "path";
    20→import { startWatcher } from "./watcher";
    21→import { parseArtifact } from "./parser";
    22→import type { ArtifactRecord, ArtifactType } from "@/types/index";
    23→
    24→export interface ArtifactIndexEvents {
    25→  /** Fired when an artifact is added or updated in the index */
    26→  change: (record: ArtifactRecord) => void;
    27→  /** Fired when an artifact is removed from the index */
    28→  remove: (relativePath: string) => void;
    29→  /** Fired when the initial scan is complete and the watcher is ready */
    30→  ready: () => void;
    31→}
    32→
    33→export class ArtifactIndex extends EventEmitter {
    34→  private projectPath: string;
    35→  private records: Map<string, ArtifactRecord> = new Map();
    36→  private watcherClose: (() => Promise<void>) | null = null;
    37→
    38→  constructor(projectPath: string) {
    39→    super();
    40→    this.projectPath = projectPath;
    41→  }
    42→
    43→  // -------------------------------------------------------------------------
    44→  // Lifecycle
    45→  // -------------------------------------------------------------------------
    46→
    47→  /**
    48→   * Perform an initial directory scan, then attach the file watcher.
    49→   * Resolves when the watcher has fired its "ready" event.
    50→   */
    51→  start(): Promise<void> {
    52→    return new Promise((resolve) => {
    53→      // Full initial scan
    54→      this.scanDirectory(this.projectPath);
    55→
    56→      const watcher = startWatcher(this.projectPath);
    57→      this.watcherClose = watcher.close.bind(watcher);
    58→
    59→      watcher.on("add", (record) => {
    60→        this.upsert(record);
    61→      });
    62→
    63→      watcher.on("change", (record) => {
    64→        this.upsert(record);
    65→      });
    66→
    67→      watcher.on("unlink", (relativePath) => {
    68→        this.remove(relativePath);
    69→      });
    70→
    71→      watcher.on("ready", () => {
    72→        this.emit("ready");
    73→        resolve();
    74→      });
    75→
    76→      watcher.on("error", (err) => {
    77→        this.emit("error", err);
    78→      });
    79→    });
    80→  }
    81→
    82→  /** Stop the watcher and clear the index. */
    83→  async stop(): Promise<void> {
    84→    if (this.watcherClose) {
    85→      await this.watcherClose();
    86→      this.watcherClose = null;
    87→    }
    88→    this.records.clear();
    89→  }
    90→
    91→  // -------------------------------------------------------------------------
    92→  // Query API
    93→  // -------------------------------------------------------------------------
    94→
    95→  /** Returns all indexed artifact records. */
    96→  getAll(): ArtifactRecord[] {
    97→    return Array.from(this.records.values());
    98→  }
    99→
   100→  /** Returns all artifacts of a given type. */
   101→  getByType(type: ArtifactType): ArtifactRecord[] {
   102→    return this.getAll().filter((r) => r.type === type);
   103→  }
   104→
   105→  /**
   106→   * Returns the artifact at the given path, or null.
   107→   * Accepts either a relative path (relative to project root) or an absolute path.
   108→   */
   109→  getByPath(filePath: string): ArtifactRecord | null {
   110→    // Normalise to relative
   111→    const relative = path.isAbsolute(filePath)
   112→      ? path.relative(this.projectPath, filePath)
   113→      : filePath;
   114→    return this.records.get(relative) ?? null;
   115→  }
   116→
   117→  // -------------------------------------------------------------------------
   118→  // Internal helpers
   119→  // -------------------------------------------------------------------------
   120→
   121→  private upsert(record: ArtifactRecord): void {
   122→    this.records.set(record.path, record);
   123→    this.emit("change", record);
   124→  }
   125→
   126→  private remove(relativePath: string): void {
   127→    this.records.delete(relativePath);
   128→

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01FQn653rFvkLVKmJisLXFGF', 'type': 'tool_result', 'content': '     1→/**
     2→ * Chokidar-based file watcher for protocol artifact directories.
     3→ * Watches .md files recursively, debounces rapid changes, and emits
     4→ * typed events: "add", "change", "unlink".
     5→ *
     6→ * Usage:
     7→ *   const emitter = startWatcher("/path/to/project", projectRoot);
     8→ *   emitter.on("add", (record) => { ... });
     9→ *   emitter.on("change", (record) => { ... });
    10→ *   emitter.on("unlink", (relativePath) => { ... });
    11→ */
    12→
    13→import chokidar from "chokidar";
    14→import { EventEmitter } from "events";
    15→import path from "path";
    16→import { parseArtifact } from "./parser";
    17→import type { ArtifactRecord } from "@/types/index";
    18→
    19→const DEBOUNCE_MS = 100;
    20→
    21→export interface WatcherEvents {
    22→  add: (record: ArtifactRecord) => void;
    23→  change: (record: ArtifactRecord) => void;
    24→  unlink: (relativePath: string) => void;
    25→  error: (err: Error) => void;
    26→  ready: () => void;
    27→}
    28→
    29→export interface ArtifactWatcher extends EventEmitter {
    30→  on<K extends keyof WatcherEvents>(event: K, listener: WatcherEvents[K]): this;
    31→  emit<K extends keyof WatcherEvents>(
    32→    event: K,
    33→    ...args: Parameters<WatcherEvents[K]>
    34→  ): boolean;
    35→  close(): Promise<void>;
    36→}
    37→
    38→/**
    39→ * Start a chokidar watcher on the given project directory.
    40→ *
    41→ * @param projectPath  Absolute path to watch
    42→ * @returns  An EventEmitter with typed add/change/unlink events + a close() method
    43→ */
    44→export function startWatcher(projectPath: string): ArtifactWatcher {
    45→  const emitter = new EventEmitter() as ArtifactWatcher;
    46→
    47→  // Debounce map: absolutePath -> timer
    48→  const pending = new Map<string, ReturnType<typeof setTimeout>>();
    49→
    50→  function scheduleEmit(event: "add" | "change", filePath: string): void {
    51→    const existing = pending.get(filePath);
    52→    if (existing) clearTimeout(existing);
    53→
    54→    const timer = setTimeout(() => {
    55→      pending.delete(filePath);
    56→      try {
    57→        const record = parseArtifact(filePath, projectPath);
    58→        emitter.emit(event, record);
    59→      } catch {
    60→        // parseArtifact should never throw, but guard defensively
    61→      }
    62→    }, DEBOUNCE_MS);
    63→
    64→    pending.set(filePath, timer);
    65→  }
    66→
    67→  const watcher = chokidar.watch(projectPath, {
    68→    ignored: [
    69→      /(^|[/\\])\.[^./]/, // hidden files/dirs (like .git)
    70→      /node_modules/,
    71→      /\.tinyshop/,
    72→    ],
    73→    persistent: true,
    74→    ignoreInitial: false,
    75→    depth: undefined,
    76→    // Only watch .md files
    77→    // chokidar doesn't support glob directly in watch path for v4; we filter in handlers
    78→  });
    79→
    80→  watcher.on("add", (filePath: string) => {
    81→    if (!filePath.endsWith(".md")) return;
    82→    scheduleEmit("add", filePath);
    83→  });
    84→
    85→  watcher.on("change", (filePath: string) => {
    86→    if (!filePath.endsWith(".md")) return;
    87→    scheduleEmit("change", filePath);
    88→  });
    89→
    90→  watcher.on("unlink", (filePath: string) => {
    91→    if (!filePath.endsWith(".md")) return;
    92→    // Cancel any pending debounced emit for this file
    93→    const existing = pending.get(filePath);
    94→    if (existing) {
    95→      clearTimeout(existing);
    96→      pending.delete(filePath);
    97→    }
    98→    const relativePath = path.relative(projectPath, filePath);
    99→    emitter.emit("unlink", relativePath);
   100→  });
   101→
   102→  watcher.on("error", (err: unknown) => {
   103→    emitter.emit("error", err instanceof Error ? err : new Error(String(err)));
   104→  });
   105→
   106→  watcher.on("ready", () => {
   107→    emitter.emit("ready");
   108→  });
   109→
   110→  // Attach close method to the emitter
   111→  (emitter as ArtifactWatcher).close = async () => {
   112→    // Clear all pending debounce timers
   113→    for (const timer of Array.from(pending.values())) {
   114→      clearTimeout(timer);
   115→    }
   116→    pending.clear();
   117→    await watcher.close();
   118→  };
   119→
   120→  return emitter;
   121→}
   122→'}]}

