     2→
     3→import {
     4→  useEffect,
     5→  useRef,
     6→  useState,
     7→  useCallback,
     8→  createContext,
     9→  useContext,
    10→} from "react";
    11→import type { SSEEvent, ArtifactRecord, RoleStatus } from "@/types";
    12→
    13→// ─── SSE Connection Status ────────────────────────────────────────────────────
    14→
    15→export type SSEStatus = "connecting" | "connected" | "disconnected";
    16→
    17→// ─── SSE Context (shared single EventSource) ─────────────────────────────────
    18→
    19→type SSEListener = (event: SSEEvent) => void;
    20→
    21→interface SSEContextValue {
    22→  status: SSEStatus;
    23→  projectPath: string | null;
    24→  addListener: (fn: SSEListener) => () => void;
    25→}
    26→
    27→export const SSEContext = createContext<SSEContextValue>({
    28→  status: "connecting",
    29→  projectPath: null,
    30→  addListener: () => () => {},
    31→});
    32→
    33→export function useSSEContext() {
    34→  return useContext(SSEContext);
    35→}
    36→
    37→/**
    38→ * Hook for components that need to listen to SSE events.
    39→ * Must be used inside SSEProvider.
    40→ */
    41→export function useSSEListener(listener: SSEListener) {
    42→  const { addListener } = useSSEContext();
    43→  const listenerRef = useRef(listener);
    44→  listenerRef.current = listener;
    45→
    46→  useEffect(() => {
    47→    const remove = addListener((event) => listenerRef.current(event));
    48→    return remove;
    49→  }, [addListener]);
    50→}
    51→
    52→/**
    53→ * Core hook that manages the single EventSource connection.
    54→ * Used by SSEProvider — not meant for direct component use.
    55→ */
    56→export function useSSEConnection() {
    57→  const [status, setStatus] = useState<SSEStatus>("connecting");
    58→  const [projectPath, setProjectPath] = useState<string | null>(null);
    59→  const listenersRef = useRef<Set<SSEListener>>(new Set());
    60→  const esRef = useRef<EventSource | null>(null);
    61→  const backoffRef = useRef<number>(2000);
    62→  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    63→  const mountedRef = useRef(true);
    64→
    65→  const addListener = useCallback((fn: SSEListener) => {
    66→    listenersRef.current.add(fn);
    67→    return () => {
    68→      listenersRef.current.delete(fn);
    69→    };
    70→  }, []);
    71→
    72→  const dispatch = useCallback((event: SSEEvent) => {
    73→    listenersRef.current.forEach((fn) => fn(event));
    74→  }, []);
    75→
    76→  const connect = useCallback(() => {
    77→    if (!mountedRef.current) return;
    78→    setStatus("connecting");
    79→
    80→    const es = new EventSource("/api/events");
    81→    esRef.current = es;
    82→
    83→    es.onmessage = (e) => {
    84→      try {
    85→        const event = JSON.parse(e.data) as SSEEvent;
    86→        if (event.type === "connected") {
    87→          setProjectPath(event.data.projectPath);
    88→          setStatus("connected");
    89→          backoffRef.current = 2000;
    90→        }
    91→        dispatch(event);
    92→      } catch {
    93→        // ignore malformed events
    94→      }
    95→    };
    96→
    97→    es.onerror = () => {
    98→      es.close();
    99→      esRef.current = null;
   100→      if (!mountedRef.current) return;
   101→      setStatus("disconnected");
   102→
   103→      const delay = backoffRef.current;
   104→      backoffRef.current = Math.min(backoffRef.current * 2, 30000);
   105→
   106→      reconnectTimerRef.current = setTimeout(() => {
   107→        if (mountedRef.current) connect();
   108→      }, delay);
   109→    };
   110→  }, [dispatch]);
   111→
   112→  useEffect(() => {
   113→    mountedRef.current = true;
   114→    connect();
   115→    return () => {
   116→      mountedRef.current = false;
   117→      if (reconnectTimerRef.current) clearTimeout(reconnectTimerRef.current);
   118→      esRef.current?.close();
   119→      esRef.current = null;
   120→    };
   121→  }, [connect]);
   122→
   123→  return { status, projectPath, addListener };
   124→}
   125→
   126→// ─── useSSEStatus ─────────────────────────────────────────────────────────────
   127→
   128→/** Returns SSE connection status for banner display. */
   129→export function useSSEStatus() {
   130→  const { status } = useSSEContext();
   131→  return status;
   132→}
