    21→        setItems(data);
    22→        // Auto-expand if items exist
    23→        if (data.length > 0) setExpanded(true);
    24→      }
    25→    } catch {
    26→      // silently fail
    27→    } finally {
    28→      setLoading(false);
    29→    }
    30→  }, []);
    31→
    32→  useEffect(() => {
    33→    fetchDecisions();
    34→    const interval = setInterval(fetchDecisions, POLL_INTERVAL);
    35→    return () => clearInterval(interval);
    36→  }, [fetchDecisions]);
    37→
    38→  const handleSourceClick = (sourceFile: string) => {
    39→    router.push(`/artifacts?path=${encodeURIComponent(sourceFile)}`);
    40→  };
    41→
    42→  return (
    43→    <section className="mt-8">
    44→      <button
    45→        onClick={() => setExpanded((v) => !v)}
    46→        className="flex items-center gap-2 w-full text-left mb-3 focus:outline-none focus-visible:ring-2 focus-visible:ring-ts-accent focus-visible:ring-offset-2 rounded"
    47→      >
    48→        {expanded ? (
    49→          <ChevronDown size={16} className="text-ts-text-muted flex-shrink-0" />
    50→        ) : (
    51→          <ChevronRight size={16} className="text-ts-text-muted flex-shrink-0" />
    52→        )}
    53→        <span className="text-base font-semibold text-ts-text">
    54→          Needs Your Attention
    55→          {items.length > 0 && (
    56→            <span className="ml-2 text-sm font-normal text-ts-text-muted">
    57→              ({items.length})
    58→            </span>
    59→          )}
    60→        </span>
    61→      </button>
    62→
    63→      {expanded && (
    64→        <div
    65→          className="space-y-3 overflow-hidden transition-all"
    66→          style={{ maxHeight: expanded ? "9999px" : "0" }}
    67→        >
    68→          {loading ? (
    69→            <div className="space-y-3">
    70→              <div className="h-[72px] rounded-xl bg-ts-surface-alt border border-ts-border animate-pulse" />
    71→              <div className="h-[72px] rounded-xl bg-ts-surface-alt border border-ts-border animate-pulse" />
    72→            </div>
    73→          ) : items.length === 0 ? (
    74→            <div className="rounded-xl border border-ts-border bg-ts-surface px-5 py-4 text-sm text-ts-text-muted">
    75→              All clear &mdash; no pending decisions.
    76→            </div>
    77→          ) : (
    78→            items.map((item) => (
    79→              <DecisionCard
    80→                key={item.id}
    81→                item={item}
    82→                onSourceClick={handleSourceClick}
    83→              />
    84→            ))
    85→          )}
    86→        </div>
    87→      )}
    88→    </section>
    89→  );
    90→}
