{'role': 'user', 'content': [{'tool_use_id': 'toolu_018w4QhPhW6dGxEuANGNSpeL', 'type': 'tool_result', 'content': '     1→/**
     2→ * POST /api/launch
     3→ *
     4→ * Body: { role: string }
     5→ *
     6→ * Integration flow:
     7→ *   1. Assemble the launch package for the given role.
     8→ *   2. Register expectedOutput with the CompletionTracker.
     9→ *   3. Emit status-update { role, status: "launched" } via EventBus.
    10→ *   4. Open Terminal.app with the terminal command via osascript.
    11→ *   5. Return { success: boolean }.
    12→ *
    13→ * Returns 400 if role is missing.
    14→ * Returns 404 if no project is attached or the role's startup prompt doesn't exist.
    15→ */
    16→
    17→import { NextRequest, NextResponse } from "next/server";
    18→import { assembleLaunchPackage } from "@/lib/launch-package";
    19→import { launchTerminal } from "@/lib/terminal-launcher";
    20→import { completionTracker } from "@/lib/artifact-engine/completion-tracker";
    21→import { eventBus } from "@/lib/artifact-engine/event-bus";
    22→import { getSettings } from "@/lib/settings";
    23→
    24→export const dynamic = "force-dynamic";
    25→
    26→export async function POST(req: NextRequest): Promise<NextResponse> {
    27→  let body: unknown;
    28→  try {
    29→    body = await req.json();
    30→  } catch {
    31→    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
    32→  }
    33→
    34→  if (
    35→    typeof body !== "object" ||
    36→    body === null ||
    37→    typeof (body as Record<string, unknown>).role !== "string"
    38→  ) {
    39→    return NextResponse.json(
    40→      { error: "Missing required field: role" },
    41→      { status: 400 }
    42→    );
    43→  }
    44→
    45→  const role = (body as Record<string, unknown>).role as string;
    46→
    47→  const settings = getSettings();
    48→  const projectPath = settings.projectPath;
    49→
    50→  if (!projectPath) {
    51→    return NextResponse.json({ error: "No project attached" }, { status: 404 });
    52→  }
    53→
    54→  // Step 1: Assemble launch package
    55→  const launchPackage = assembleLaunchPackage(role, projectPath);
    56→
    57→  if (!launchPackage) {
    58→    return NextResponse.json(
    59→      { error: `Startup prompt not found for role: ${role}` },
    60→      { status: 404 }
    61→    );
    62→  }
    63→
    64→  // Step 2: Register expectedOutput watch BEFORE emitting launched so the
    65→  // tracker is ready if the file appears very quickly
    66→  if (launchPackage.expectedOutput) {
    67→    await completionTracker.watch(role, launchPackage.expectedOutput, projectPath);
    68→  }
    69→
    70→  // Step 3: Emit launched status
    71→  eventBus.broadcast({
    72→    type: "status-update",
    73→    data: { role, status: "launched" },
    74→  });
    75→
    76→  // Step 4: Open terminal (non-blocking — we return success even if the
    77→  // terminal open itself had an issue, because the package was assembled)
    78→  const launchResult = await launchTerminal(launchPackage.terminalCommand);
    79→
    80→  if (!launchResult.success) {
    81→    // Terminal open failed but we already emitted launched — return the error
    82→    // so the frontend can surface it, while still reporting the launch attempt
    83→    return NextResponse.json(
    84→      { success: false, error: launchResult.error },
    85→      { status: 500 }
    86→    );
    87→  }
    88→
    89→  return NextResponse.json({ success: true });
    90→}
    91→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_017Wu6pnzqtRukCidMx7VUog', 'type': 'tool_result', 'content': '     1→/**
