    15→
    16→export const dynamic = "force-dynamic";
    17→
    18→export async function POST(req: NextRequest): Promise<NextResponse> {
    19→  let body: BootstrapFormData & { force?: boolean };
    20→  try {
    21→    body = await req.json();
    22→  } catch {
    23→    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
    24→  }
    25→
    26→  const { name, stack, description, path: targetPath, force = false } = body;
    27→
    28→  if (!name || !stack || !description || !targetPath) {
    29→    return NextResponse.json(
    30→      { error: "Missing required fields: name, stack, description, path" },
    31→      { status: 400 }
